lity": "general", "usage_tags": ["anglicism"], "why": "ознаки за перевіркою словника"}, {"k": "tost", "register": "standard", "regionality": "general", "usage_tags": ["anglicism"], "why": "ознаки за перевіркою словника"}, {"k": "trailer", "register": "standard", "regionality": "general", "usage_tags": ["anglicism"], "why": "ознаки за перевіркою словника"}, {"k": "trenirka", "register": "colloquial", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "u dobre ruke", "register": "standard", "regionality": "general", "usage_tags": ["idiom"], "why": "ознаки за перевіркою словника"}, {"k": "u pravu si", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "u zadnji čas", "register": "standard", "regionality": "general", "usage_tags": ["idiom"], "why": "ознаки за перевіркою словника"}, {"k": "vidimo se", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "vikend", "register": "standard", "regionality": "general", "usage_tags": ["anglicism"], "why": "ознаки за перевіркою словника"}, {"k": "web-stranica", "register": "standard", "regionality": "general", "usage_tags": ["anglicism"], "why": "ознаки за перевіркою словника"}, {"k": "za van", "register": "standard", "regionality": "general", "usage_tags": [], "why": "за правилами регістру"}, {"k": "zaslužio si", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "zdravo", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "zlonamjerni softver", "register": "standard", "regionality": "general", "usage_tags": ["anglicism"], "why": "ознаки за перевіркою словника"}, {"k": "znači...", "register": "standard", "regionality": "general", "usage_tags": [], "why": "за правилами регістру"}, {"k": "zovi policiju", "register": "informal", "regionality": "general", "usage_tags": [], "why": "звертання на «ти» в самому виразі (офіційно — на «ви»)"}, {"k": "zubar", "register": "standard", "regionality": "general", "usage_tags": [], "why": "за правилами регістру"}, {"k": "ćevapi", "register": "standard", "regionality": "general", "usage_tags": ["turkism"], "why": "ознаки за перевіркою словника"}, {"k": "čekaj", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "čika", "register": "colloquial", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "čujemo se", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "šalabahter", "register": "colloquial", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "škampi", "register": "standard", "regionality": "general", "usage_tags": ["italianism"], "why": "ознаки за перевіркою словника"}, {"k": "šlag", "register": "standard", "regionality": "general", "usage_tags": ["germanism"], "why": "ознаки за перевіркою словника"}, {"k": "šminka", "register": "standard", "regionality": "general", "usage_tags": ["germanism"], "why": "ознаки за перевіркою словника"}, {"k": "šogor", "register": "standard", "regionality": "general", "usage_tags": ["germanism"], "why": "ознаки за перевіркою словника"}, {"k": "šogorica", "register": "standard", "regionality": "general", "usage_tags": ["germanism"], "why": "ознаки за перевіркою словника"}, {"k": "šprica", "register": "colloquial", "regionality": "general", "usage_tags": ["germanism"], "why": "регістр уже був"}, {"k": "štand", "register": "standard", "regionality": "general", "usage_tags": ["germanism"], "why": "ознаки за перевіркою словника"}, {"k": "što radiš", "register": "informal", "regionality": "general", "usage_tags": [], "why": "звертання на «ти» в самому виразі (офіційно — на «ви»)"}, {"k": "štrudla", "register": "standard", "regionality": "general", "usage_tags": ["germanism"], "why": "ознаки за перевіркою словника"}, {"k": "šugaman", "register": "colloquial", "regionality": "Dalmatia", "usage_tags": ["italianism"], "why": "старе regional → colloquial; регіон уже був"}, {"k": "želim ti", "register": "informal", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}, {"k": "žmigavac", "register": "colloquial", "regionality": "general", "usage_tags": [], "why": "регістр уже був"}]'::jsonb)
             as t(k text, register text, regionality text, usage_tags text[], why text)
  loop
    select * into x from public.lexemes where lower(lemma) = w.k;
    if x.id is null then
      v_lex_missing := v_lex_missing + 1;
      continue;
    end if;
    if x.usage_tags is not null then
      v_lex_same := v_lex_same + 1;
      continue;
    end if;
    v_reg := case when x.register is null or x.register in ('regional', 'non_standard') then w.register else x.register end;
    v_region := coalesce(x.regionality, w.regionality);
    insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
    values ('lexeme', x.id, coalesce((select max(version) from public.content_versions
                                      where entity_type = 'lexeme' and entity_id = x.id), 0) + 1,
            to_jsonb(x), c_reason || ' — ' || w.why);
    update public.lexemes
       set register = v_reg, regionality = v_region, usage_tags = w.usage_tags,
           version = coalesce(version, 1) + 1, updated_at = now()
     where id = x.id;
    insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
    values ('lexeme', x.id, x.status, x.status, 'auto_passed', 'script',
            jsonb_build_array(jsonb_build_object('register', v_reg, 'regionality', v_region, 'usage_tags', to_jsonb(w.usage_tags))),
            c_reason || ' — ' || w.why);
    v_lex := v_lex + 1;
  end loop;

  -- 2. Решта слів: standard / general / {} (старі regional / non_standard → colloquial — на випадок, якщо їх немає в списку)
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'lexeme', l.id, coalesce((select max(cv.version) from public.content_versions cv
                                   where cv.entity_type = 'lexeme' and cv.entity_id = l.id), 0) + 1,
         to_jsonb(l), c_reason || ' — типові мітки (не в правилах): standard / general / {}'
    from public.lexemes l
   where l.usage_tags is null or l.register is null or l.regionality is null;

  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  select 'lexeme', l.id, l.status, l.status, 'auto_passed', 'script', '[]'::jsonb,
         c_reason || ' — типові мітки (не в правилах): standard / general / {}'
    from public.lexemes l
   where l.usage_tags is null or l.register is null or l.regionality is null;

  update public.lexemes
     set register = case when register is null then 'standard'
                         when register in ('regional', 'non_standard') then 'colloquial' else register end,
         regionality = coalesce(regionality, 'general'),
         usage_tags = coalesce(usage_tags, '{}'::text[]),
         version = coalesce(version, 1) + 1, updated_at = now()
   where usage_tags is null or register is null or regionality is null;
  get diagnostics v_lex_rest = row_count;

  -- 3. Речення за списком
  for w in select * from jsonb_to_recordset('[{"k": "imamo li blokada za ovaj sprint?", "register": "standard", "regionality": "general", "usage_tags": ["professional_jargon", "anglicism"], "why": "ІТ-жаргон: sprint, blokada (блокер)"}, {"k": "kužiš?", "register": "colloquial", "regionality": "general", "usage_tags": [], "why": "kužiti — розмовне"}, {"k": "predao sam zahtjev online.", "register": "standard", "regionality": "general", "usage_tags": ["anglicism"], "why": "online"}]'::jsonb)
             as t(k text, register text, regionality text, usage_tags text[], why text)
  loop
    select * into p from public.phrases where lower(text_hr) = w.k;
    if p.id is null or p.usage_tags is not null then
      continue;
    end if;
    insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
    values ('phrase', p.id, coalesce((select max(version) from public.content_versions
                                      where entity_type = 'phrase' and entity_id = p.id), 0) + 1,
            to_jsonb(p), c_reason || ' — ' || w.why);
    update public.phrases
       set register = coalesce(p.register, w.register), regionality = coalesce(p.regionality, w.regionality),
           usage_tags = w.usage_tags, version = coalesce(version, 1) + 1, updated_at = now()
     where id = p.id;
    insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
    values ('phrase', p.id, p.status, p.status, 'auto_passed', 'script', '[]'::jsonb, c_reason || ' — ' || w.why);
    v_phr := v_phr + 1;
  end loop;

  -- 4. Решта речень
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  select 'phrase', ph.id, coalesce((select max(cv.version) from public.content_versions cv
                                   where cv.entity_type = 'phrase' and cv.entity_id = ph.id), 0) + 1,
         to_jsonb(ph), c_reason || ' — типові мітки: standard / general / {}'
    from public.phrases ph
   where ph.usage_tags is null or ph.register is null or ph.regionality is null;

  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  select 'phrase', ph.id, ph.status, ph.status, 'auto_passed', 'script', '[]'::jsonb,
         c_reason || ' — типові мітки: standard / general / {}'
    from public.phrases ph
   where ph.usage_tags is null or ph.register is null or ph.regionality is null;

  update public.phrases
     set register = coalesce(register, 'standard'), regionality = coalesce(regionality, 'general'),
         usage_tags = coalesce(usage_tags, '{}'::text[]), version = coalesce(version, 1) + 1, updated_at = now()
   where usage_tags is null or register is null or regionality is null;
  get diagnostics v_phr_rest = row_count;

  -- Самоперевірка: міток без значення й старих значень не лишилось
  select (select count(*) from public.lexemes where register is null or regionality is null or usage_tags is null)
       + (select count(*) from public.phrases where register is null or regionality is null or usage_tags is null)
    into v_left;
  if v_left > 0 then
    raise exception 'Лишились рядки без міток: %', v_left;
  end if;
  if exists (select 1 from public.lexemes where register in ('regional', 'non_standard')) then
    raise exception 'Лишились старі значення register (regional / non_standard)';
  end if;
  raise notice 'Готово: слів явно %, слів типово %, уже було %, немає в базі %, речень явно %, речень типово %, без міток %',
    v_lex, v_lex_rest, v_lex_same, v_lex_missing, v_phr, v_phr_rest, v_left;
end
$fix$;

